@dataclass
class EvaluatedCase:
    """One generated case, its actual model output, and its diagnostic result.

    ``forecast`` is absent when model execution failed. Positional scenario
    and seed identities keep repeated scenario kinds and seeds distinct.
    """

    case: Case
    forecast: Forecast | None
    result: CaseResult
    scenario_index: int
    seed_index: int


# %% ../source/07_pipeline.ipynb #07_pipeline-09
@dataclass
class ForecastRun:
    """Retain the evidence needed to inspect a run without fitting again.

    Arrays remain in memory; ``report`` uses the JSON report schema and does
    not embed contexts, observations, or forecast arrays. ``titles``
    optionally names each scenario position in plain words for the plots (a
    scorecard sets them to the pattern and noise level); they are not saved
    in the report.
    """

    cases: list[EvaluatedCase]
    metadata: dict[str, Any] = field(default_factory=dict)
    titles: list[str] = field(default_factory=list)

    @classmethod
    def from_forecasts(
        cls,
        cases,
        forecasts,
        *,
        metadata=None,
        scores=None,
        checks=None,
        check_dependence=False,
        n_calibration=99,
        alpha=0.05,
        dependence_seed_offset=100_000,
    ):
        """Check and score forecasts made earlier, one per case, without a model.

        ``forecasts[i]`` is the forecast recorded for ``cases[i]``, in any form
        a model's ``predict`` may return: a list or NumPy array, a pandas Series
        or DataFrame, or a ``Forecast``. ``None`` means nothing was recorded,
        and that case fails "Runs without errors". Each forecast gets the output
        checks and scores of ``Pipeline.run``, and the run's report and plots
        work as usual. ``metadata`` is added to the run's metadata, for example
        ``{"model": "weather service"}``. ``scores`` records more scores and
        ``checks`` adds output checks of your own, as in ``Pipeline.run``. No
        model is kept, so these cases cannot be replayed.
        """
        from timegym.diagnostics import _describe_checks, _describe_scores
        from timegym.pipeline import _as_forecast, _evaluate_ready_made
        from timegym.provenance import diagnostic_settings, runtime_provenance

        if isinstance(cases, Case):
            raise TypeError("cases must be a list of Case objects, not one Case")
        if metadata is not None and not isinstance(metadata, dict):
            raise TypeError("metadata must be a dictionary or None")
        cases, forecasts = list(cases), list(forecasts)
        if len(forecasts) != len(cases):
            raise ValueError(
                f"Got {len(forecasts)} forecasts for {len(cases)} cases; pass one "
                "forecast per case, in the same order"
            )
        settings = diagnostic_settings(
            check_dependence=check_dependence,
            n_calibration=n_calibration,
            alpha=alpha,
            dependence_seed_offset=dependence_seed_offset,
        )
        requested = {} if scores is None else {"scores": _describe_scores(scores)}
        if checks is not None:
            requested["checks"] = _describe_checks(checks)

        def recorded(position, case):
            if forecasts[position] is None:
                raise ValueError("No forecast was recorded for this case")
            return _as_forecast(forecasts[position], case.task)

        results = _evaluate_ready_made(cases, recorded, settings, scores, checks)
        return cls(
            cases=results,
            metadata={
                **runtime_provenance(),
                "model": "recorded forecasts",
                "diagnostic_settings": settings,
                **requested,
                **(metadata or {}),
            },
        )

    @property
    def report(self) -> TestReport:
        """Return the usual structured report for these evaluated cases."""
        return TestReport(
            cases=[entry.result for entry in self.cases], metadata=self.metadata
        )

    def plot_forecasts(self, *, show_quantiles=False, figsize=None, history=None):
        """Draw ``timegym.plotting.plot_forecasts`` for this run's retained forecasts."""
        from timegym.plotting import plot_forecasts

        return plot_forecasts(
            self, show_quantiles=show_quantiles, figsize=figsize, history=history
        )

    def plot_errors(
        self, metric="mean_reference_mse", *, bins=None, missing="raise", figsize=None
    ):
        """Draw ``timegym.plotting.plot_errors`` for this run's retained scores."""
        from timegym.plotting import plot_errors

        return plot_errors(
            self, metric=metric, bins=bins, missing=missing, figsize=figsize
        )
